        return;
      }

      delete statData.关系系统[name];

      await replaceLatestMvuData(mvuData);

      if (typeof toastr !== 'undefined') {
        toastr.success(`已遗忘与 ${name} 的关系`);
      }

      window.dispatchEvent(new CustomEvent('mvu-data-updated'));
